From 58b6167336d301e582e59e12a0ac92cafb96397c Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 12:04:47 +0100
Subject: [PATCH] xdgactivation: keep launch feedback for every pending
 activation

Only the last requested token kept its launch feedback, so starting a
second app while the first was still loading removed the first app's
busy indicator. Track feedback per token and end only the window's own.

BUG: 492448
---
 src/xdgactivationv1.cpp | 36 ++++++++++++++++++++++++------------
 src/xdgactivationv1.h   | 15 +++++++++++----
 2 files changed, 35 insertions(+), 16 deletions(-)

diff --git a/src/xdgactivationv1.cpp b/src/xdgactivationv1.cpp
index ce6cce956f..3e2fdbe0dd 100644
--- a/src/xdgactivationv1.cpp
+++ b/src/xdgactivationv1.cpp
@@ -47,15 +47,14 @@ XdgActivationV1Integration::XdgActivationV1Integration(XdgActivationV1Interface
 {
     connect(Workspace::self(), &Workspace::windowAdded, this, [this](Window *window) {
         if (window->isActive()) {
-            clearFeedback();
+            clearFeedback(window);
         }
     });

     connect(Workspace::self(), &Workspace::windowActivated, this, [this](Window *window) {
-        if (!m_activation || !window || m_lastTokenAppId != window->desktopFileName()) {
-            return;
+        if (window) {
+            clearFeedback(window);
         }
-        clearFeedback();
     });

     activation->setActivationTokenCreator([this](ClientConnection *client, SurfaceInterface *surface, uint serial, SeatInterface *seat, const QString &appId) -> QString {
@@ -93,9 +92,10 @@ QString XdgActivationV1Integration::requestToken(bool isPrivileged, SurfaceInter
         icon = QIcon::fromTheme(df.readIcon(), icon);
     }
     if (showNotify) {
-        m_lastToken = newToken;
-        m_lastTokenAppId = appId;
-        m_activation = waylandServer()->plasmaActivationFeedback()->createActivation(appId);
+        m_activations[newToken] = Activation{
+            .appId = appId,
+            .feedback = waylandServer()->plasmaActivationFeedback()->createActivation(appId),
+        };
     }
     if (isPrivileged) {
         // plasmashell doesn't have a valid serial unless it has keyboard focus,
@@ -131,14 +131,26 @@ void XdgActivationV1Integration::activateSurface(SurfaceInterface *surface, cons
         window->demandAttention();
     }

-    clearFeedback();
+    clearFeedback(token);
 }

-void XdgActivationV1Integration::clearFeedback()
+void XdgActivationV1Integration::clearFeedback(Window *window)
 {
-    if (m_activation) {
-        Q_EMIT effects->startupRemoved(m_lastToken);
-        m_activation.reset();
+    clearFeedback(window->activationToken());
+    for (auto it = m_activations.begin(); it != m_activations.end();) {
+        if (it->second.appId == window->desktopFileName()) {
+            Q_EMIT effects->startupRemoved(it->first);
+            it = m_activations.erase(it);
+        } else {
+            ++it;
+        }
+    }
+}
+
+void XdgActivationV1Integration::clearFeedback(const QString &token)
+{
+    if (m_activations.erase(token)) {
+        Q_EMIT effects->startupRemoved(token);
     }
 }

diff --git a/src/xdgactivationv1.h b/src/xdgactivationv1.h
index c609d3cbdd..3ff85fb868 100644
--- a/src/xdgactivationv1.h
+++ b/src/xdgactivationv1.h
@@ -16,6 +16,8 @@
 #include <QObject>
 #include <QPointer>

+#include <map>
+
 namespace KWin
 {

@@ -24,6 +26,7 @@ class ClientConnection;
 class SurfaceInterface;
 class XdgActivationV1Interface;
 class PlasmaWindowActivationInterface;
+class Window;

 class KWIN_EXPORT XdgActivationV1Integration : public QObject
 {
@@ -40,11 +43,15 @@ public:

 private:
     QString requestToken(bool isPrivileged, SurfaceInterface *surface, UInt32Serial serial, SeatInterface *seat, const QString &appId);
-    void clearFeedback();
+    void clearFeedback(Window *window);
+    void clearFeedback(const QString &token);

-    QString m_lastToken;
-    QString m_lastTokenAppId;
-    std::unique_ptr<PlasmaWindowActivationInterface> m_activation;
+    struct Activation
+    {
+        QString appId;
+        std::unique_ptr<PlasmaWindowActivationInterface> feedback;
+    };
+    std::map<QString, Activation> m_activations;
 };

 }
